function paintHeld() {
  var word = document.getElementById('f2');
  var shown = document.querySelector('.game-timer-held');
  if (shown && word) shown.textContent = word.textContent;
  var state = (typeof noacgMachineState === 'function') ? noacgMachineState() : null;
