}

// The renderClock hook: drain the bar across the foot of the band.
function clockPainted(left, total) {
  var fill = document.querySelector('.game-timer-progress-fill');
  if (fill && total > 0) fill.style.transform = 'scaleX(' + Math.max(0, Math.min(1, left / total)) + ')';
}

// Hold the label to three rows: it keeps its full size for any normal title and steps down
// (never under 44px) only when the operator writes more than three rows' worth.
function fitLabel() {
  var el = document.getElementById('f0');
  if (!el) return;
  el.style.fontSize = '';
  var cs = window.getComputedStyle(el);
  var size = parseFloat(cs.fontSize);
  if (!size) return;
  var rows = 3;
  var floor = Math.min(size, 44);
  for (var i = 0; i < 12 && size > floor; i++) {
    var line = parseFloat(window.getComputedStyle(el).lineHeight) || size * 1.14;
    if (el.scrollHeight <= line * rows + 2) break;
    size = Math.max(floor, size - 4);
    el.style.fontSize = size + 'px';
  }
}
